insert into public.services (id, name, line, summary, price_min_cop, price_max_cop, duration, source_path) values
  ('capacitacion-realidad-virtual', 'Capacitación en entornos inmersivos (realidad virtual)', 'quality_assurance', 'Desarrollamos experiencias de realidad virtual para entrenar al personal en procedimientos críticos, estándares de calidad y seguridad industrial, sin detener la operación ni exponer a las personas a riesgos.', 6000000, 20000000, '6 a 10 semanas', 'data/catalog/servicios/capacitacion-realidad-virtual.md'),
  ('diagnostico-madurez-digital-ia', 'Diagnóstico de madurez digital y de IA para MIPYMES', 'business_innovation', 'Evaluamos qué tan preparada está la empresa para adoptar herramientas digitales e inteligencia artificial: procesos, datos, personas y tecnología. Entregamos una hoja de ruta realista con oportunidades priorizadas por impacto y esfuerzo.', 1500000, 4000000, '2 a 3 semanas', 'data/catalog/servicios/diagnostico-madurez-digital-ia.md'),
  ('digitalizacion-procesos-administrativos', 'Modelado y digitalización de procesos administrativos', 'process_design', 'Documentamos los procesos administrativos de la empresa (compras, facturación, inventario, atención al cliente) con notación BPMN, eliminamos pasos que no agregan valor y definimos cómo digitalizarlos con herramientas accesibles para una MIPYME.', 5000000, 18000000, '4 a 10 semanas', 'data/catalog/servicios/digitalizacion-procesos-administrativos.md'),
  ('formulacion-proyectos-idi', 'Gerencia y formulación de proyectos de innovación (I+D+i)', 'business_innovation', 'Formulamos proyectos de investigación, desarrollo e innovación para presentarlos a convocatorias de financiadores públicos, privados o de cooperación internacional. Si el proyecto es aprobado, podemos acompañar su gerencia: plan de trabajo, seguimiento técnico y financiero, e informes.', 4000000, 15000000, '3 a 8 semanas', 'data/catalog/servicios/formulacion-proyectos-idi.md'),
  ('gestion-calidad-control-estadistico', 'Sistema de gestión de calidad y control estadístico de procesos', 'quality_assurance', 'Ayudamos a la empresa a reducir defectos y a cumplir estándares de calidad: análisis de causas raíz, control estadístico de procesos (gráficos de control, capacidad de proceso), estandarización de procedimientos y preparación para certificaciones como ISO 9001.', 6000000, 20000000, '6 a 12 semanas', 'data/catalog/servicios/gestion-calidad-control-estadistico.md'),
  ('produccion-mas-limpia-desperdicios', 'Producción más limpia y reducción de desperdicios', 'process_design', 'Aplicamos herramientas de manufactura esbelta (lean) y producción más limpia para reducir desperdicios de materia prima, energía y agua, y para ajustar la producción a la demanda real. Mejora la rentabilidad y la sostenibilidad del proceso.', 3500000, 12000000, '4 a 8 semanas', 'data/catalog/servicios/produccion-mas-limpia-desperdicios.md'),
  ('prototipado-3d', 'Prototipado 3D y fabricación rápida', 'business_innovation', 'Diseñamos y fabricamos prototipos físicos de productos, piezas o empaques con modelado CAD, impresión 3D (FDM y resina) y corte láser, para validar forma, función y aceptación de clientes antes de producir en serie.', 2500000, 12000000, '2 a 6 semanas', 'data/catalog/servicios/prototipado-3d.md'),
  ('simulacion-operaciones', 'Simulación de operaciones y análisis "what if"', 'process_design', 'Construimos un modelo de simulación de eventos discretos de la operación de la empresa (manufactura, logística o servicios) para encontrar cuellos de botella y comparar escenarios antes de invertir. Usamos software especializado de simulación y teoría de colas para estimar tiempos de espera, utilización de recursos y capacidad.', 8000000, 25000000, '4 a 8 semanas', 'data/catalog/servicios/simulacion-operaciones.md'),
  ('tablero-indicadores-analitica', 'Tablero de indicadores y analítica operativa', 'process_design', 'Definimos los indicadores clave del negocio y construimos un tablero que se actualiza con los datos que la empresa ya tiene (ventas, inventario, producción, atención), para tomar decisiones con datos y no por intuición.', 4000000, 14000000, '3 a 6 semanas', 'data/catalog/servicios/tablero-indicadores-analitica.md'),
  ('vigilancia-tecnologica-pi', 'Vigilancia tecnológica y propiedad intelectual', 'business_innovation', 'Acompañamos a la empresa a proteger lo que crea: búsqueda de antecedentes de marcas y patentes, estrategia de propiedad intelectual y preparación de la solicitud de **registro de marca ante la Superintendencia de Industria y Comercio (SIC)**. También hacemos vigilancia tecnológica: qué están haciendo los competidores y qué tecnologías emergen en el sector.', 1800000, 6000000, '2 a 4 semanas', 'data/catalog/servicios/vigilancia-tecnologica-pi.md')
insert into public.requests (company, contact_name, contact_email, line, problem_summary, recommended_services, scope, investment_range_cop, status, is_demo_seed) values
  ('Hotel Brisas de Getsemaní', 'Marcela Pérez', null, 'process_design', 'Hotel boutique de 24 habitaciones en Getsemaní, Cartagena. En temporada alta (diciembre–enero) se forman filas de hasta 40 minutos en el check-in entre las 2 y las 5 p. m. Tienen 2 recepcionistas. Llegan unos 18 huéspedes por hora en el pico y cada check-in toma unos 6 minutos. Los huéspedes se quejan en las reseñas.', array['simulacion-operaciones']::text[], 'Simulación del check-in en temporada alta: comparar 2, 3 y 4 recepcionistas y check-in digital previo.', 'COP 8.000.000 – 25.000.000', 'in_review', true),
  ('Panadería El Trigal', 'Jorge Díaz', null, 'process_design', 'Panadería con tres sedes en Turbaco. Al final del día botamos una parte grande del pan porque producimos siempre la misma cantidad, sin importar el día de la semana.', array['produccion-mas-limpia-desperdicios', 'tablero-indicadores-analitica']::text[], 'Cuantificar el desperdicio por sede y día, y ajustar la producción a la demanda.', 'COP 3.500.000 – 12.000.000', 'new', true),
  ('Confecciones Mompox', 'Luz Marina Ortega', null, 'quality_assurance', 'Taller de confecciones de 30 operarias. Un cliente grande nos devolvió un lote porque muchas prendas tenían costuras torcidas y medidas fuera de tolerancia. Los defectos cambian mucho entre turnos.', array['gestion-calidad-control-estadistico']::text[], 'Análisis de causas raíz y control estadístico en el proceso de costura.', 'COP 6.000.000 – 20.000.000', 'proposal_sent', true),
  ('Logística Bahía', 'Ricardo Villalba', null, 'process_design', 'Operador logístico cerca del Puerto de Cartagena. Los camiones esperan hasta 3 horas para cargar en el muelle de despacho en las mañanas. Tenemos 3 muelles y cada carga toma unos 50 minutos.', array['simulacion-operaciones']::text[], 'Simulación del muelle de despacho y escenarios de citas escalonadas y un cuarto muelle.', 'COP 8.000.000 – 25.000.000', 'new', true),
  ('Manglar Labs', 'Valentina Rojas', null, 'business_innovation', 'Somos una startup que hace bolsos con fibras recicladas. Queremos exportar y alguien nos dijo que primero deberíamos proteger la marca. No sabemos si el nombre ya está registrado.', array['vigilancia-tecnologica-pi']::text[], 'Búsqueda de antecedentes de la marca y preparación de la solicitud ante la SIC.', 'COP 1.800.000 – 6.000.000', 'closed', true),
  ('Cooperativa de Pescadores de Bocachica', 'Efraín Julio', null, 'business_innovation', 'Somos una cooperativa de 45 pescadores. Queremos montar un centro de acopio con cadena de frío y buscar financiación para un proyecto de innovación, pero nunca hemos presentado un proyecto a una convocatoria.', array['formulacion-proyectos-idi']::text[], 'Identificar convocatorias y formular el proyecto del centro de acopio con cadena de frío.', 'COP 4.000.000 – 15.000.000', 'in_review', true);
